#!/usr/bin/env node
// mcp-headers.mjs <server>: print the HTTP headers .mcp.json declares for one MCP server, as JSON.
//
// Codex reads it through `http_headers_helper` (see .codex/config.toml, generated by
// ./sync-codex-config.mjs), so the bearer token stays in .mcp.json, the one file both Claude Code
// and Codex take MCP config from, and is never copied into .codex/. `${VAR}` / `${VAR:-default}`
// placeholders are expanded from the environment, the way Claude Code expands them.
// Prints {} when the server or its headers are missing (Codex then connects without them).
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
const name = process.argv[2]
const expand = (v) => String(v).replace(/\$\{([A-Za-z_][A-Za-z0-9_]*)(?::-([^}]*))?\}/g, (_, k, d) => process.env[k] ?? d ?? '')

let headers = {}
try {
  const server = JSON.parse(fs.readFileSync(path.join(ROOT, '.mcp.json'), 'utf8'))?.mcpServers?.[name]
  if (server?.headers && typeof server.headers === 'object') {
    headers = Object.fromEntries(Object.entries(server.headers).map(([k, v]) => [k, expand(v)]))
  }
} catch { /* no .mcp.json: no headers */ }
process.stdout.write(JSON.stringify(headers))
